static void on_signal(uv_signal_t *sig, int signum) {
  uv_stop(sig->loop);
}

int main(void) {
  uv_loop_t *loop = uv_default_loop();
  uv_tcp_t server;
  uv_signal_t sig;
  struct sockaddr_in addr;
  uv_ip4_addr("0.0.0.0", 7000, &addr);
  uv_tcp_init(loop, &server);
  uv_tcp_bind(&server, (const struct sockaddr *)&addr, 0);
  int rc = uv_listen((uv_stream_t *)&server, 128, on_connection);
  if (rc != 0) {
    fprintf(stderr, "listen: %s\n", uv_strerror(rc));
    return 1;
  }
  uv_signal_init(loop, &sig);
  uv_signal_start(&sig, on_signal, SIGINT);
  uv_run(loop, UV_RUN_DEFAULT);
  rc = uv_loop_close(loop);
  if (rc != 0) fprintf(stderr, "loop close: %s\n", uv_strerror(rc));
  return rc == 0 ? 0 : 1;
}

static void close_rest(uv_handle_t *handle, void *arg) {
  if (!uv_is_closing(handle)) uv_close(handle, on_close);
}

static void on_signal(uv_signal_t *sig, int signum) {
  uv_close((uv_handle_t *)sig->data, NULL);
  uv_close((uv_handle_t *)sig, NULL);
  uv_walk(sig->loop, close_rest, NULL);
}

uv_signal_init(loop, &sig);
sig.data = &server;
uv_signal_start(&sig, on_signal, SIGINT);
uv_run(loop, UV_RUN_DEFAULT);
